#include "service.hpp"
#include <poll.h>
#include <unistd.h>
#include <sstream>
#include <chrono>
struct Scene {int epoch=-1;std::vector<PageResources*> pages;std::vector<unsigned> counts;std::vector<float> vertices;std::vector<int> generations;};
struct Output {
 std::unique_ptr<TextLab> v;std::unique_ptr<Engine> e;Scene scene;bool paused=false;size_t peakPages=0,peakSubmissions=0;VkDeviceSize peakBytes=0,peakStaging=0;
 VkDeviceSize bytes(){VkDeviceSize n=0;for(auto&s:e->submissions)for(auto*b:{&s->staging,&s->vertices,&s->colorRead,&s->velocityRead,&s->idRead})n+=b->size;return n;}
 VkDeviceSize staging(){VkDeviceSize n=0;for(auto&s:e->submissions)n+=s->staging.size;return n;}
 void observe(){peakPages=std::max(peakPages,size_t(e->livePages()));peakSubmissions=std::max(peakSubmissions,e->submissions.size());peakBytes=std::max(peakBytes,bytes());peakStaging=std::max(peakStaging,staging());}
 SubmissionResources& upload(PageResources&p,const std::vector<float>&m){auto&s=e->upload(p,m);observe();return s;}
 SubmissionResources& drawBatch(const std::vector<PageResources*>&p,const std::vector<unsigned>&c,const std::vector<float>&v,uint64_t gate=0){auto&s=e->drawBatch(p,c,v,gate);observe();return s;}
 Output(const char* shaders){v=std::make_unique<TextLab>(shaders);if(!v->validation)throw std::runtime_error("validation unavailable");e=std::make_unique<Engine>(*v);e->freeImage(v->coverage);}
 bool publish(const Scene& s){if(s.epoch<=scene.epoch||s.pages.empty()||s.pages.size()>2||s.pages.size()!=s.counts.size()||s.pages.size()!=s.generations.size())return false;size_t count=0;for(size_t i=0;i<s.pages.size();i++){auto*p=s.pages[i];if(!p||p->owner!=v->device||!p->live||p->canceled||!p->uploadComplete||p->generation<0||p->generation!=s.generations[i]||s.counts[i]%6||!s.counts[i]||s.counts[i]>48)return false;count+=s.counts[i];}if(s.vertices.size()!=count*4)return false;scene=s;return true;}
 SubmissionResources& draw(uint64_t gate=0){if(paused)throw std::runtime_error("output paused");if(scene.epoch<0)throw std::runtime_error("scene unavailable");for(size_t i=0;i<scene.pages.size();i++)if(scene.pages[i]->generation!=scene.generations[i])throw std::runtime_error("snapshot page generation mismatch");return drawBatch(scene.pages,scene.counts,scene.vertices,gate);}
 void retire(PageResources&p){if(std::find(scene.pages.begin(),scene.pages.end(),&p)!=scene.pages.end())throw std::runtime_error("current scene pin");e->retire(p);}
 PageResources& page(int gen){if(e->livePages()>=2)throw std::runtime_error("native page capacity");auto&p=e->page(gen);observe();return p;}
 void release(){for(auto&s:e->submissions){if(s->pending)throw std::runtime_error("release pending");if(s->fb)vkDestroyFramebuffer(v->device,s->fb,nullptr);e->freeImage(s->target);e->freeImage(s->velocity);e->freeImage(s->id);e->freeBuffer(s->staging);e->freeBuffer(s->vertices);e->freeBuffer(s->colorRead);e->freeBuffer(s->velocityRead);e->freeBuffer(s->idRead);vkDestroyFence(v->device,s->fence,nullptr);vkFreeCommandBuffers(v->device,v->pool,1,&s->cb);}for(auto&p:e->pages)p->uploadSubmission=nullptr;e->submissions.clear();e->pages.erase(std::remove_if(e->pages.begin(),e->pages.end(),[](auto&p){return !p->live;}),e->pages.end());}
 ~Output(){scene={};e.reset();v.reset();}
};
static std::string line(){std::string s;auto deadline=std::chrono::steady_clock::now()+std::chrono::seconds(30);for(;;){auto left=std::chrono::duration_cast<std::chrono::milliseconds>(deadline-std::chrono::steady_clock::now()).count();if(left<=0)throw std::runtime_error("IPC read timeout");pollfd p{STDIN_FILENO,POLLIN,0};int r=poll(&p,1,int(left));if(r<=0)throw std::runtime_error("IPC read timeout/error");char c;auto n=::read(STDIN_FILENO,&c,1);if(n!=1)throw std::runtime_error("IPC EOF");if(c=='\n')return s;if(s.size()>=64)throw std::runtime_error("IPC command budget");s+=c;}}
static std::vector<float> data(const std::filesystem::path& dir,const char*name,bool mask){auto a=read((dir/name).c_str());if(mask){if(a.size()!=3185)throw std::runtime_error("mask dimensions");for(float x:a)if(x<0||x>1)throw std::runtime_error("mask range");}else{if(a.empty()||a.size()>216||a.size()%24)throw std::runtime_error("vertices size");for(size_t k=0;k<a.size();k+=4)if(std::abs(a[k])>1||std::abs(a[k+1])>1||a[k+2]<0||a[k+2]>1||a[k+3]<0||a[k+3]>1)throw std::runtime_error("vertex bounds");}return a;}
static Scene single(PageResources*p,const std::vector<float>&v,int epoch){return Scene{epoch,{p},{unsigned(v.size()/4)},v,{p->generation}};}
static Scene pairScene(PageResources*p,PageResources*q,const std::vector<float>&a,const std::vector<float>&b,int epoch){Scene s{epoch,{p,q},{unsigned(a.size()/4),unsigned(b.size()/4)},a,{p->generation,q->generation}};s.vertices.insert(s.vertices.end(),b.begin(),b.end());return s;}
int main(int argc,char**argv){try{
 if(argc!=4)throw std::runtime_error("SHADERS REQUESTROOT NEWOUT");std::filesystem::path root=argv[2],out=argv[3];if(!std::filesystem::create_directory(out))throw std::runtime_error("existing output");
 {auto A=std::make_unique<Output>(argv[1]);Output B(argv[1]);if(A->v->device==B.v->device)throw std::runtime_error("same logical device");SubmissionResources *aPending=nullptr,*bPending=nullptr,*upload=nullptr;PageResources *candidate=nullptr;std::vector<float> oldVertices,newVertices;std::ofstream events(out/"events.jsonl");int seq=0,stage=0;
 auto aHeld=[&](){if(!A||!aPending||vkGetFenceStatus(A->v->device,aPending->fence)!=VK_NOT_READY)throw std::runtime_error("A pending evidence");uint64_t n=99;VK(vkGetSemaphoreCounterValue(A->v->device,A->e->gate,&n));if(n!=0)throw std::runtime_error("A gate changed");};
 auto ack=[&](const std::string&op){std::ostringstream s;s<<"{\"seq\":"<<seq<<",\"op\":\""<<op<<"\",\"A_live_pages\":"<<(A?A->e->livePages():0)<<",\"A_submissions\":"<<(A?A->e->submissions.size():0)<<",\"B_live_pages\":"<<B.e->livePages()<<",\"B_submissions\":"<<B.e->submissions.size()<<",\"B_epoch\":"<<B.scene.epoch<<",\"A_buffer_bytes\":"<<(A?A->bytes():0)<<",\"B_buffer_bytes\":"<<B.bytes()<<",\"A_staging_bytes\":"<<(A?A->staging():0)<<",\"B_staging_bytes\":"<<B.staging()<<",\"A_peak_buffer_bytes\":"<<(A?A->peakBytes:0)<<",\"B_peak_buffer_bytes\":"<<B.peakBytes<<",\"A_peak_submissions\":"<<(A?A->peakSubmissions:0)<<",\"B_peak_submissions\":"<<B.peakSubmissions<<"}";events<<s.str()<<'\n';events.flush();std::cout<<"ACK "<<s.str()<<std::endl;};
 ack("READY");bool done=false;
 while(!done){auto l=line();std::istringstream parser(l);std::string op,extra;int n;if(!(parser>>op>>n)||(parser>>extra)||n!=seq+1)throw std::runtime_error("IPC sequence");seq=n;auto dir=root/std::to_string(seq);
 if(op=="INIT"&&stage==0){auto mask=data(dir,"page0.f32",true);oldVertices=data(dir,"old.f32",false);if(oldVertices.size()!=192)throw std::runtime_error("initial eight instances");auto&ap=A->page(0);auto&au=A->upload(ap,mask);A->e->wait(au);if(!A->publish(single(&ap,oldVertices,0)))throw std::runtime_error("A scene publish");A->release();aPending=&A->draw(1);A->paused=true;size_t before=A->e->submissions.size();bool rejected=false;try{A->draw();}catch(const std::runtime_error&e){if(std::string(e.what())!="output paused")throw;rejected=true;}if(!rejected||A->e->submissions.size()!=before)throw std::runtime_error("pause guard");auto&bp=B.page(0);auto&bu=B.upload(bp,mask);B.e->wait(bu);if(!B.publish(single(&bp,oldVertices,0)))throw std::runtime_error("B scene publish");auto&d=B.draw();B.e->wait(d);dump(d,out/"B-initial");B.release();aHeld();stage=1;
 }else if(op=="PREPARE"&&stage==1){aHeld();auto mask=data(dir,"page1.f32",true);newVertices=data(dir,"new.f32",false);if(newVertices.size()!=24)throw std::runtime_error("one new glyph");bPending=&B.draw(1);candidate=&B.page(1);upload=&B.upload(*candidate,mask);if(vkGetFenceStatus(B.v->device,bPending->fence)!=VK_NOT_READY||vkGetFenceStatus(B.v->device,upload->fence)!=VK_NOT_READY)throw std::runtime_error("B not pending");if(B.publish(pairScene(B.scene.pages[0],candidate,oldVertices,newVertices,1)))throw std::runtime_error("published incomplete upload");stage=2;
 }else if(op=="CANCEL"&&stage==2){aHeld();B.e->cancel(*candidate);if(B.publish(pairScene(B.scene.pages[0],candidate,oldVertices,newVertices,1)))throw std::runtime_error("published canceled");bool rejected=false;try{B.retire(*candidate);}catch(const std::runtime_error&e){if(std::string(e.what())!="page retirement with pending consumers")throw;rejected=true;}if(!rejected)throw std::runtime_error("pending retired");stage=3;
 }else if(op=="RELEASE_B"&&stage==3){B.e->signal(1);B.e->wait(*bPending);B.e->wait(*upload);dump(*bPending,out/"B-old-held");if(B.publish(pairScene(B.scene.pages[0],candidate,oldVertices,newVertices,1)))throw std::runtime_error("completed canceled publish");B.retire(*candidate);B.release();candidate=nullptr;upload=nullptr;bPending=nullptr;aHeld();stage=4;
 }else if(op=="GROW"&&stage==4){aHeld();auto mask=data(dir,"page1.f32",true);auto nv=data(dir,"new.f32",false);if(nv!=newVertices)throw std::runtime_error("retry UV changed");auto&next=B.page(2);auto&u=B.upload(next,mask);B.e->wait(u);auto old=B.scene;if(!B.publish(pairScene(old.pages[0],&next,oldVertices,newVertices,2))||B.publish(old))throw std::runtime_error("scene epoch guard");auto stalePage=B.scene;stalePage.epoch=3;stalePage.generations[1]++;if(B.publish(stalePage))throw std::runtime_error("page generation mismatch accepted");auto foreign=B.scene;foreign.epoch=3;foreign.pages[0]=A->scene.pages[0];if(B.publish(foreign))throw std::runtime_error("foreign scene");bool pinned=false;try{B.retire(*old.pages[0]);}catch(const std::runtime_error&e){if(std::string(e.what())!="current scene pin")throw;pinned=true;}if(!pinned)throw std::runtime_error("scene pin missing");size_t beforeCap=B.e->pages.size();bool capRejected=false;try{B.page(3);}catch(const std::runtime_error&e){if(std::string(e.what())!="native page capacity")throw;capRejected=true;}if(!capRejected||B.e->pages.size()!=beforeCap)throw std::runtime_error("native cap side effects");auto&d=B.draw();B.e->wait(d);dump(d,out/"B-grown");B.release();aHeld();stage=5;
 }else if(op=="STATE"&&stage>=5){if(A&&aPending)aHeld();
 }else if(op=="WRONG"&&stage==5){aHeld();auto pages=B.scene.pages;pages[1]=pages[0];auto&d=B.drawBatch(pages,B.scene.counts,B.scene.vertices);B.e->wait(d);dump(d,out/"wrong-page");B.release();
 }else if(op=="RELEASE_A"&&stage==5){aHeld();A->e->signal(1);A->e->wait(*aPending);dump(*aPending,out/"A-old-released");aPending=nullptr;A->release();A.reset();if(validationErrors)throw std::runtime_error("A destruction validation");auto&d=B.draw();B.e->wait(d);dump(d,out/"B-after-A-destroyed");B.release();stage=6;
 }else if(op=="REBUILD_A"&&stage==6){A=std::make_unique<Output>(argv[1]);if(A->v->device==B.v->device)throw std::runtime_error("rebuilt device ownership");auto m0=data(dir,"page0.f32",true),m1=data(dir,"page1.f32",true);auto&ap=A->page(0);auto&aq=A->page(2);auto&u0=A->upload(ap,m0);auto&u1=A->upload(aq,m1);A->e->wait(u0);A->e->wait(u1);if(!A->publish(pairScene(&ap,&aq,oldVertices,newVertices,0)))throw std::runtime_error("rebuilt scene");auto&d=A->draw();A->e->wait(d);dump(d,out/"A-rebuilt");A->release();auto&b=B.draw();B.e->wait(b);dump(b,out/"B-after-A-rebuilt");B.release();stage=7;
 }else if(op=="SHUTDOWN"&&stage==7){A.reset();B.scene={};for(auto&p:B.e->pages)B.retire(*p);B.release();done=true;stage=8;
 }else throw std::runtime_error("IPC state/opcode");ack(op);
 }
 }if(validationErrors)throw std::runtime_error("final validation");std::cout<<"SERVICE_DESTROYED validation_enabled=1"<<std::endl;return 0;
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
